//! Cargo-driven `ddraw.dll` link, generated by tools/cargo_cell_gen.py
//! from the cmake link it replaces.
//! The body is ddraw-rust; reactos-link builds the PE.

use reactos_link::{Linker, ModuleKind, MsvcrtexKind};
use std::env;

fn main() {
    let arch = env::var("CARGO_CFG_TARGET_ARCH").expect("CARGO_CFG_TARGET_ARCH");
    let (target_json, entry, image_base) = match arch.as_str() {
        "x86" => ("i686-pc-windows-gnu", "_DllMainCRTStartup@12", Some(0x757a0000u64)),
        "x86_64" => ("x86_64-pc-windows-gnu", "DllMainCRTStartup", Some(0x7ff34000000u64)),
        "aarch64" => ("aarch64-pc-windows-gnullvm", "DllMainCRTStartup", Some(0x7ff34000000u64)),
        o => panic!("ddraw-cargo: unsupported arch {o}"),
    };

    let link_order: &[&str] = match arch.as_str() {
        "x86" => &["body", "dll/directx/wine/ddraw/ddraw_classes_r.o", "engine:wine", "engine:c:wine_dll_register", "engine:c:wine_dll_canunload", "engine:c:dxguid", "engine:uuid", "engine:pseh", "import:d3dwine", "import:user32", "import:gdi32", "import:advapi32", "import:msvcrt", "import:kernel32", "import:ntdll", "engine:chkstk", "engine:oldnames"],
        "x86_64" => &["body", "dll/directx/wine/ddraw/ddraw_classes_r.o", "engine:wine", "engine:c:wine_dll_register", "engine:c:wine_dll_canunload", "engine:c:dxguid", "engine:uuid", "engine:pseh", "import:d3dwine", "import:user32", "import:gdi32", "import:advapi32", "import:msvcrt", "import:kernel32", "import:ntdll", "engine:oldnames"],
        "aarch64" => &["body", "dll/directx/wine/ddraw/ddraw_classes_r.o", "engine:wine", "engine:c:wine_dll_register", "engine:c:wine_dll_canunload", "engine:c:dxguid", "engine:uuid", "engine:pseh", "import:d3dwine", "import:user32", "import:gdi32", "import:advapi32", "import:msvcrt", "import:kernel32", "import:ntdll", "engine:chkstk", "engine:oldnames"],
        _ => unreachable!(),
    };

    // The module's part of cmake's windres command; reactos-link adds what every
    // module shares from reactos-link/cflags/rc.<arch>.flags (Linker::rc).
    let rc_includes: &[&str] = &[
        "@build/dll/directx/wine/ddraw",
        "dll/directx/wine/ddraw",
        "@build/sdk/include/wine",
        "sdk/include/wine",
        "@std",
        "vendor/opengl-headers/include",
        "vendor/libdxg/include",
        "vendor/vkd3d/include",
        "vendor/vkd3d/include/private",
        "sdk/lib/pseh/include",
        "sdk/lib/tdilib",
        "vendor/zlib/include",
        "vendor/libtiff/include",
    ];
    let rc_flags: &[&str] = &[];
    let rc_defines: &[&str] = &[
        "UNICODE",
        "WINVER=0x502",
        "_CRT_DECLARE_NONSTDC_NAMES=1",
        "_CRT_NONSTDC_NO_DEPRECATE",
        "_DLL",
        "_UNICODE",
        "_WIN32_WINNT=0x502",
        "__ROS_LONG64__",
        "__USE_CRTIMP",
        "__WINESRC__",
    ];

    // The body passes floats by value: i386 user code needs SSE (see oleaut32).
    let body_rustflags = match arch.as_str() {
        "x86" => Some("-C target-feature=+sse,+sse2"),
        _ => None,
    };
    let mut link = Linker::new(target_json);
    if let Some(flags) = body_rustflags {
        link = link.rust_build_rustflags(flags);
    }
    link
        .rust_staticlib("ddraw-rust")
        .c_from_compile_db("ddraw_shims", &["dll/directx/wine/ddraw/rust_cohab_stub.c"])
        .rc("dll/directx/wine/ddraw/version.rc", rc_includes, rc_flags, rc_defines)
        .spec2def("dll/directx/wine/ddraw/ddraw.spec", "ddraw.dll")
        .spec_stubs()
        .import_lib("dll/directx/wine/wined3d/wined3d.spec", "d3dwine.dll", "d3dwine")
        .import_lib("win32ss/user/user32/user32.spec", "user32.dll", "user32")
        .import_lib("win32ss/gdi/gdi32/gdi32.spec", "gdi32.dll", "gdi32")
        .import_lib("dll/win32/advapi32/advapi32.spec", "advapi32.dll", "advapi32")
        .import_lib("dll/win32/msvcrt/msvcrt.spec", "msvcrt.dll", "msvcrt")
        .import_lib("dll/win32/kernel32/kernel32.spec", "kernel32.dll", "kernel32")
        .import_lib("dll/ntdll/def/ntdll.spec", "ntdll.dll", "ntdll")
        // The body, import libs and static libs in cmake's link order: the first
        // to define a symbol wins. cmake-built ones are reused until each has a
        // cargo home; `engine:` ones reactos-link builds.
        .link_order(link_order)
        .msvcrtex_crt(MsvcrtexKind::Dll)
        .link(ModuleKind::Win32Dll {
            entry: entry.into(),
            image_base,
            subsystem: None,
        });
}
